"use client"
import { usePathname } from "next/navigation";
import { SidebarProvider, useSidebar } from "../context/PatientsidebarContext";
import { useEffect } from "react";
import ProtectedRoute from "@/components/ProtectedRoute";
import Sidebar from "@/components/Sidebar";

export default function PatientLayout({ children }) {
  return (
    <SidebarProvider>
      <PatientLayoutInner>{children}</PatientLayoutInner>
    </SidebarProvider>
  );
}

function PatientLayoutInner({ children }) {
  const pathname = usePathname();
  const { mode, setMode } = useSidebar();

  const isDashboard = pathname === "/patient/dashboard";

  useEffect(() => {
    setMode(isDashboard ? "full" : "mini");
  }, [pathname]);

  const handleSidebarToggle = () => {
    setMode((prev) => (prev === "full" ? "mini" : "full"));
  };

  return (
    <ProtectedRoute>
      <div className="flex min-h-screen bg-gray-100">
        <Sidebar
          mode={mode}
          onToggleMode={isDashboard ? handleSidebarToggle : undefined}
          isDoctor={false}
        />
        <div className="flex-1 flex flex-col transition-all duration-300">
          <Navbar open={mode === "full"} setOpen={handleSidebarToggle} />
          <main className="flex-1 p-4 md:p-8">{children}</main>
        </div>
      </div>
    </ProtectedRoute>
  );
}
