"use client";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { Button } from "./ui/button";
import {
  LayoutDashboard,
  CalendarCheck,
  UserPlus,
  FileText,
  User,
  Stethoscope,
  NotebookPen,
  CalendarPlus
} from "lucide-react";

const patientLinks = [
  { name: "Dashboard", href: "/patient/dashboard", icon: LayoutDashboard },
  { name: "Appointments", href: "/patient/appointments", icon: CalendarCheck },
  { name: "Doctors", href: "/patient/doctors", icon: Stethoscope },
  { name: "Profile", href: "/patient/profile", icon: User },
  { name: "Health History", href: "/patient/health-history", icon: FileText },
];

// Doctor sidebar links with icons
const doctorLinks = [
  { name: "Dashboard", href: "/doctor/dashboard", icon: LayoutDashboard },
  {
    name: "My Appointments",
    href: "/doctor/appointments",
    icon: CalendarCheck,
  },
  { name: "Add Dates", href: "/doctor/availability", icon:CalendarPlus },
  { name: "Patients", href: "/doctor/patients", icon: UserPlus },
  {
    name: "Write Prescription",
    href: "/doctor/prescription",
    icon: NotebookPen,
  },
  { name: "Profile", href: "/doctor/profile", icon: User },
];

export default function Sidebar({ mode = "full", onToggleMode, isDoctor }) {
  const pathname = usePathname();
  const linksToRender = isDoctor ? doctorLinks : patientLinks;
  const isFull = mode === "full";

  return (
    <aside
      className={`bg-gray-100 z-50 shadow-md h-screen transition-all duration-200 flex flex-col fixed text mt-20 
        ${isFull ? "w-64 p-4" : "w-20 p-4"}
      `}
    >
      <nav className="flex flex-col gap-2">
        {linksToRender.map(({ name, href, icon: Icon }) => (
          <Link
            key={href}
            href={href}
            className={`flex items-center ${
              isFull ? "gap-3 px-4 py-2" : "justify-center py-2"
            } rounded hover:bg-blue-100 transition-colors
              ${
                pathname === href
                  ? "bg-blue-100 font-semibold text-blue-700"
                  : "text-gray-700"
              }
            `}
          >
            <Icon className="w-5 h-5" />
            {isFull && <span>{name}</span>}
          </Link>
        ))}
      </nav>
    </aside>
  );
}
